// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.translationimport com.roshan.persona.voice.stt.SupportedLanguage/** * NOUS — Live Translation Configuration + Session (§10 Live Speech Translation). * * Live bidirectional translation between two speakers speaking different * languages. NOUS sits in the middle: hears Speaker A in language A, translates * to language B, speaks the translation to Speaker B (and vice versa). * * ## Architecture (§10) * * ``` * Speaker A (English)              Speaker B (Hindi) *       ↓                                ↓ *    STT (en)                         STT (hi) *       ↓                                ↓ *    LLM Translate (en→hi)           LLM Translate (hi→en) *       ↓                                ↓ *    TTS (hi, NOUS persona)          TTS (en, NOUS persona) *       ↓                                ↓ *    Speaker B hears Hindi           Speaker A hears English * ``` * * ## Persona voice, NOT cloned (§25 Q7) * * Per the confirmed decision Q7, live translation uses **NOUS's persona * voice** — NOT a cloned voice of either speaker. Rationale: cloning adds * ~1 s of latency per utterance (VITS adaptation + synthesis), which would * bust the §15 latency budget of < 1.5 s for live translation. The persona * voice is already loaded and can synthesize immediately. * * ## Bidirectional mode * * The engine runs both directions in parallel — Speaker A's utterances are * translated A→B and played to B, while Speaker B's utterances are * translated B→A and played to A. Speaker identification (Step 5.7) routes * each utterance to the correct direction. * * ## 32 supported languages (§10) * * Per §10, NOUS supports 32 languages for live translation. The full list * is in [SupportedLanguage] (Step 5.3) — same enum used by the STT language * detector. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§10 Live Speech Translation, §25 Q7 persona voice, §15 Performance Budgets</a> *//** * Configuration for one live translation session. * * @param languageA       first speaker's language (ISO 639-1). * @param languageB       second speaker's language (ISO 639-1). * @param direction       which direction(s) to translate (A→B, B→A, or both). * @param usePartialResults  if true (default), translate partial STT results *                            for lower latency. If false, wait for final STT *                            results (higher accuracy, higher latency). * @param maxUtteranceSeconds  hard cap on utterance length (default 15 s). * @param translateEngine     function that translates text: (text, from, to) → translated. */data class LiveTranslationConfig(    val languageA: SupportedLanguage,    val languageB: SupportedLanguage,    val direction: TranslationDirection = TranslationDirection.BIDIRECTIONAL,    val usePartialResults: Boolean = true,    val maxUtteranceSeconds: Int = DEFAULT_MAX_UTTERANCE_SECONDS,    val translateEngine: TranslateEngine? = null,) {    init {        require(languageA != languageB) {            "languageA ($languageA) must differ from languageB ($languageB)"        }        require(maxUtteranceSeconds in 1..120) {            "maxUtteranceSeconds must be 1..120, got $maxUtteranceSeconds"        }    }    companion object {        /** §15 Performance Budgets: Live translation (one direction) < 1.5 s. */        const val TARGET_LATENCY_MS = 1500L        /** Default max utterance length before forcing a translation. */        const val DEFAULT_MAX_UTTERANCE_SECONDS = 15        /** All 32 supported translation languages (from §10). */        val SUPPORTED_LANGUAGES: List<SupportedLanguage> = SupportedLanguage.entries    }}// ──────────────────────────────────────────────────────────────────────────/** Which direction(s) to translate. */enum class TranslationDirection {    /** Only translate A → B (Speaker A's words reach Speaker B). */    A_TO_B,    /** Only translate B → A (Speaker B's words reach Speaker A). */    B_TO_A,    /** Translate both directions (default for live conversation). */    BIDIRECTIONAL,}// ──────────────────────────────────────────────────────────────────────────/** * Functional interface for the translation engine (real impl uses LLM). * * Decoupled from the LLM provider so tests can inject a fake without * spinning up Module 4's LlamaCppProvider or OkHttpCloudProvider. * * The real implementation (wired in Step 5.14) uses the Cloud LLM with a * prompt like: "Translate the following from {from} to {to}. Reply with * only the translation, no preamble." */fun interface TranslateEngine {    /**     * Translate [text] from language [from] to language [to].     *     * @return the translated text, or null on failure.     */    suspend fun translate(text: String, from: SupportedLanguage, to: SupportedLanguage): String?}// ──────────────────────────────────────────────────────────────────────────/** * State of one live translation session. * * The engine emits state transitions as a StateFlow so the UI can show * "Listening to Speaker A…", "Translating…", "Speaking to Speaker B…". */enum class TranslationSessionState {    /** Session not started. */    IDLE,    /** Listening to Speaker A (capturing audio for STT). */    LISTENING_A,    /** Listening to Speaker B. */    LISTENING_B,    /** Translating captured utterance. */    TRANSLATING,    /** Speaking translated text via TTS. */    SPEAKING,    /** Session paused (user pressed pause). */    PAUSED,    /** Session ended (user pressed stop or error). */    ENDED,}// ──────────────────────────────────────────────────────────────────────────/** * One translated utterance. * * @param direction        which direction this translation went. * @param sourceText       original text from the speaker. * @param sourceLanguage   speaker's language. * @param translatedText   translated text. * @param targetLanguage   listener's language. * @param latencyMs        total time from STT final to TTS done (target < 1.5 s). * @param timestampMs      when this translation completed. */data class TranslatedUtterance(    val direction: TranslationDirection,    val sourceText: String,    val sourceLanguage: SupportedLanguage,    val translatedText: String,    val targetLanguage: SupportedLanguage,    val latencyMs: Long,    val timestampMs: Long = System.currentTimeMillis(),) {    init {        require(sourceText.isNotBlank()) { "sourceText must not be blank" }        require(translatedText.isNotBlank()) { "translatedText must not be blank" }        require(sourceLanguage != targetLanguage) {            "source and target languages must differ"        }        require(latencyMs >= 0) { "latencyMs must be non-negative" }    }}